<?php
if(!defined('ABSPATH'))exit;
function eicr_core_page_services(){
 $html='<div class="core-page-intro"><p>Browse electrical, gas, fire-safety, energy and property-compliance services for residential and commercial properties across London and the M25 area.</p></div><div class="core-service-grid">';
 foreach(eicr_service_catalog() as $row){[$slug,$title,$price,$benefit]=$row;$html.='<article><h2>'.esc_html($title).'</h2><p>'.esc_html($benefit).'</p><div><strong class="core-price-display">'.eicr_service_price_by_slug_html($slug).'</strong><span><a href="'.esc_url(home_url('/services/'.$slug.'/')).'">More details</a><a class="core-book" href="'.esc_url(home_url('/booking/?service='.$slug)).'">Book now</a></span></div></article>';}
 return $html.'</div>';
}
add_shortcode('eicr_all_services','eicr_core_page_services');
function eicr_core_page_pricing(){
 $html='<div class="core-page-intro"><p>Clear starting prices for London property inspections and certification services. Select a service to view its details or start a booking.</p></div><div class="core-price-list">';
 foreach(eicr_service_catalog() as $row){[$slug,$title,$price]=$row;$html.='<div><a href="'.esc_url(home_url('/services/'.$slug.'/')).'">'.esc_html($title).'</a><strong class="core-price-display">'.eicr_service_price_by_slug_html($slug).'</strong><a class="core-book" href="'.esc_url(home_url('/booking/?service='.$slug)).'">Book</a></div>';}
 return $html.'</div>';
}
add_shortcode('eicr_pricing','eicr_core_page_pricing');
function eicr_core_page_areas(){return '<div class="core-page-intro"><p>EICR In London provides domestic and commercial property-compliance services throughout all 32 London boroughs, the City of London and suitable locations around the M25.</p></div><div class="core-area-grid"><article><h2>Central London</h2><p>City of London, Westminster, Camden, Islington, Kensington and Chelsea, Lambeth and Southwark.</p></article><article><h2>North London</h2><p>Barnet, Brent, Enfield, Haringey, Harrow and Waltham Forest.</p></article><article><h2>East London</h2><p>Barking and Dagenham, Bexley, Greenwich, Hackney, Havering, Newham, Redbridge and Tower Hamlets.</p></article><article><h2>South London</h2><p>Bromley, Croydon, Kingston upon Thames, Lewisham, Merton, Richmond upon Thames, Sutton and Wandsworth.</p></article><article><h2>West London</h2><p>Ealing, Hammersmith and Fulham, Hillingdon and Hounslow.</p></article><article><h2>Greater London &amp; M25</h2><p>Ask our team to confirm availability for your postcode and required service.</p></article></div>';}add_shortcode('eicr_service_areas','eicr_core_page_areas');
function eicr_core_page_about(){return '<div class="core-copy"><h2>London property-compliance specialists</h2><p>EICR In London supports landlords, homeowners, estate agents, home buyers and sellers with coordinated electrical, gas, energy, fire-safety and health-and-safety services.</p><h2>Qualified and suitable engineers</h2><p>Each request is matched to the appropriate specialist and scope. We focus on clear communication, organised appointments and practical digital reports.</p><h2>Residential and commercial support</h2><p>Our team serves domestic and commercial properties throughout London and suitable locations around the M25.</p><p><a class="core-cta" href="'.esc_url(home_url('/booking/')).'">Book an inspection</a></p></div>';}add_shortcode('eicr_about','eicr_core_page_about');
function eicr_core_page_contact(){$o=get_option('eicr_settings',[]);$phone=$o['phone']??'+44 7878 655350';$email=$o['email']??'info@eicrinlondon.co.uk';$address=$o['address']??'Unit 16, Office 2, Midas Business Centre, Wantz Road, Dagenham, RM10 8PS';return '<div class="core-contact-grid"><article><h2>Contact our team</h2><p>Tell us which service you need, the property type and the London postcode. We will help you choose the appropriate inspection.</p><p><strong>Phone</strong><br><a href="tel:'.esc_attr(preg_replace('/[^0-9+]/','',$phone)).'">'.esc_html($phone).'</a></p><p><strong>Email</strong><br><a href="mailto:'.esc_attr($email).'">'.esc_html($email).'</a></p><p><strong>Service location</strong><br>'.esc_html($address).'</p><p><strong>Opening hours</strong><br>24hr call out services<br>Monday–Sunday</p></article><div>'.do_shortcode('[eicr_quote]').'</div></div>';}add_shortcode('eicr_contact','eicr_core_page_contact');
function eicr_legal_details(){
 $settings=(array)get_option('eicr_settings',[]);
 return[
  'name'=>trim((string)($settings['legal_business_name']??''))?:'EICR in London',
  'address'=>trim((string)($settings['address']??''))?:'Unit 16, Office 2, Midas Business Centre, Wantz Road, Dagenham, RM10 8PS',
  'email'=>sanitize_email($settings['privacy_email']??'')?:sanitize_email($settings['email']??'')?:get_option('admin_email'),
  'phone'=>trim((string)($settings['phone']??''))?:'+44 7878 655350',
  'company_number'=>trim((string)($settings['company_number']??'')),
  'ico_registration'=>trim((string)($settings['ico_registration']??'')),
 ];
}
function eicr_legal_identity_html($details){
 $extra='';
 if($details['company_number'])$extra.='<br>Company number: '.esc_html($details['company_number']);
 if($details['ico_registration'])$extra.='<br>ICO registration: '.esc_html($details['ico_registration']);
 return '<p><strong>'.esc_html($details['name']).'</strong><br>'.esc_html($details['address']).'<br>Email: <a href="mailto:'.esc_attr($details['email']).'">'.esc_html($details['email']).'</a><br>Phone: '.esc_html($details['phone']).$extra.'</p>';
}
function eicr_privacy_policy_shortcode(){
 $d=eicr_legal_details();
 return '<div class="core-copy eicr-legal-copy"><p><strong>Last updated:</strong> 7 August 2026</p><p>This notice explains how '.esc_html($d['name']).' handles personal information when you browse this website, ask for a quote, create an account, book work, make a payment, submit a review or receive certificates.</p><h2>Who controls your information</h2>'.eicr_legal_identity_html($d).'<h2>Information we collect</h2><p>We may collect your name, contact details, service and property information, appointment preferences, access notes, booking and payment status, account identifiers, correspondence, reviews, certificates and basic technical or security logs. Google, Apple, Facebook or Microsoft may provide a verified account identifier, name and email when you choose a connected sign-in option. Stripe processes card details directly; we receive transaction references and payment status rather than full card details.</p><h2>Why we use it</h2><p>We use information to answer enquiries, take steps before a contract, manage bookings, arrange and deliver services, take payment, issue invoices and certificates, secure customer accounts, prevent misuse, maintain business records and comply with legal obligations. The usual lawful bases are contract, legal obligation and our legitimate interests in operating and protecting the service. We rely on consent where required for optional analytics, campaign measurement or marketing.</p><h2>Who receives it</h2><p>Information may be shared only as necessary with authorised operations staff, the assigned engineer or service partner, website and email hosting providers, payment processors, account sign-in providers, professional advisers, regulators and authorities. Operations staff can access service-delivery details but not payment amounts or owner-only website settings. Analytics or campaign-measurement providers may receive device or usage information only under the applicable consent choices.</p><h2>International transfers</h2><p>Some technology providers operate outside the United Kingdom. Where personal information is transferred internationally, we rely on the provider\'s applicable transfer safeguards and contractual protections.</p><h2>How long we keep it</h2><p>Quote and enquiry records are normally kept for up to 24 months. Booking, payment and invoice records are normally kept for up to six years where needed for tax, accounting, contractual or dispute purposes. Account and certificate records are kept while the account is active and for any further period reasonably needed for those purposes. Reviews remain published until removed or consent is withdrawn where applicable. Security logs are kept only as long as reasonably necessary.</p><h2>Cookies, analytics and campaign measurement</h2><p>Essential technologies support security, sign-in and requested site functions. If enabled and accepted, optional Google Analytics or Google Ads conversion tags may measure visits and actions connected with marketing campaigns. The website theme does not insert third-party advertising space or display ads. See our <a href="'.esc_url(home_url('/cookies/')).'">Cookie Policy</a> for more detail.</p><h2>Your rights</h2><p>Depending on the circumstances, you may ask for access, correction, deletion, restriction or transfer of your personal information, object to certain use, or withdraw consent. Contact us using the privacy email above. You may also complain to the <a href="https://ico.org.uk/make-a-complaint/" target="_blank" rel="noopener">Information Commissioner\'s Office</a>.</p><h2>Security and changes</h2><p>We use access controls and other reasonable safeguards, but no internet service can guarantee absolute security. We may update this notice when our services or legal requirements change; the latest version will remain on this page.</p></div>';
}
add_shortcode('eicr_privacy_policy','eicr_privacy_policy_shortcode');
function eicr_cookie_policy_shortcode(){
 $d=eicr_legal_details();
 return '<div class="core-copy eicr-legal-copy"><p><strong>Last updated:</strong> 7 August 2026</p><p>This policy explains how '.esc_html($d['name']).' uses cookies and similar storage or access technologies.</p><h2>Essential technologies</h2><p>Essential technologies support security, WordPress sessions, customer and staff sign-in, booking submission, payment protection and saved consent choices. These are used where necessary to provide a service you request or protect the website.</p><h2>Analytics</h2><p>If enabled and accepted, analytics helps us understand visits, popular pages and website performance. Analytics is not required to browse public pages or make a booking.</p><h2>Google Ads campaign measurement</h2><p>If enabled and accepted, Google Ads conversion measurement may record actions such as enquiries or completed bookings that follow a campaign visit. It does not create advertising space or display third-party ads on this website.</p><h2>Connected sign-in and payments</h2><p>Google, Apple, Facebook or Microsoft sign-in is contacted only when you choose the relevant option. Stripe resources are loaded on the booking page when card payment is configured and selected. Their own privacy and cookie terms also apply.</p><h2>Managing choices</h2><p>Use the Cookie settings link in the website footer to review or change optional choices. You can also manage cookies in your browser, although blocking essential technologies may prevent account, booking or payment features from working. For privacy questions, email <a href="mailto:'.esc_attr($d['email']).'">'.esc_html($d['email']).'</a>.</p></div>';
}
add_shortcode('eicr_cookie_policy','eicr_cookie_policy_shortcode');
function eicr_terms_shortcode(){
 $d=eicr_legal_details();
 return '<div class="core-copy eicr-legal-copy"><p><strong>Last updated:</strong> 7 August 2026</p><p>These terms apply to website enquiries, booking requests and services arranged by '.esc_html($d['name']).'. They do not limit rights that cannot lawfully be excluded.</p><h2>Booking requests and confirmation</h2><p>Submitting the form records a request; it does not by itself guarantee an appointment. We review the property, requested scope, location, access and specialist availability. A booking becomes confirmed when we expressly confirm the date, scope and price. We may propose a different time or decline work we cannot safely or appropriately provide.</p><h2>Scope and prices</h2><p>Website prices are starting prices unless clearly stated otherwise. The final price may depend on property size, number of items, system condition, access, parking, congestion charges and any additional work you authorise. Work outside the confirmed scope requires further agreement.</p><h2>Payment</h2><p>Available payment methods are shown at booking. Card payments are processed by Stripe. Bank-transfer or cash arrangements must be completed by the agreed due date. A certificate or final record may be withheld where payment lawfully remains due.</p><h2>Changes and cancellation</h2><p>Tell us as soon as possible if access, scope or timing changes. Reasonable cancellation or wasted-visit charges may apply where stated and agreed before confirmation. Consumers who enter a distance contract may have a statutory 14-day cancellation right. If you expressly ask for work to start during that period, you may need to pay for services supplied; the right can end once the service is fully performed following the required request and acknowledgement.</p><h2>Property access and safety</h2><p>You must provide accurate information, lawful authority to arrange the work and safe, reasonable access to the relevant areas, equipment and utilities. Tell us about known hazards, vulnerable occupants, parking restrictions, alarms, pets or special access requirements before the visit.</p><h2>Specialists, reports and certificates</h2><p>We may use suitably qualified employees or trusted service partners for the relevant scope. Reports and certificates reflect the accessible areas, system condition and agreed checks at the time of attendance. They must not be altered or used for a different property or purpose. Recommendations or limitations recorded in a report should be followed promptly.</p><h2>Liability</h2><p>Nothing excludes liability where exclusion is unlawful, including liability for death or personal injury caused by negligence, fraud or fraudulent misrepresentation. Subject to that, we are not responsible for hidden defects, inaccessible areas, inaccurate information supplied by others or losses that were not reasonably foreseeable from the confirmed service.</p><h2>Complaints and contact</h2><p>Contact us promptly with the booking reference and details of any concern so we can investigate. Our contact details are:</p>'.eicr_legal_identity_html($d).'<p>These terms are governed by the law of England and Wales. Consumers retain any mandatory right to use the courts available to them.</p></div>';
}
add_shortcode('eicr_terms','eicr_terms_shortcode');
function eicr_ensure_core_pages(){
 $old_privacy='<h2>Information we collect</h2><p>We use the details you provide to respond to enquiries, manage bookings, arrange inspections, process authorised payments and send service documentation.</p><h2>How information is used</h2><p>Customer information is used only for legitimate business administration, service delivery and legal obligations. Contact us if you need access to or correction of your information.</p>';
 $old_terms='<h2>Bookings and quotations</h2><p>Prices shown are starting prices unless a fixed quotation is confirmed. Final scope, access requirements and any authorised additional work are agreed with the customer.</p><h2>Appointments</h2><p>Appointment availability depends on service, property location and engineer availability. Customers should provide safe and reasonable access to the inspection areas.</p>';
 $pages=['services'=>['All Services','[eicr_all_services]'],'pricing'=>['Pricing','[eicr_pricing]'],'areas'=>['Service Areas','[eicr_service_areas]'],'about'=>['About Us','[eicr_about]'],'contact'=>['Contact','[eicr_contact]'],'privacy'=>['Privacy Policy','[eicr_privacy_policy]'],'cookies'=>['Cookie Policy','[eicr_cookie_policy]'],'terms'=>['Terms & Conditions','[eicr_terms]']];
 foreach($pages as $slug=>$data){
  $page=get_page_by_path($slug,OBJECT,'page');
  if(!$page){wp_insert_post(['post_type'=>'page','post_status'=>'publish','post_title'=>$data[0],'post_name'=>$slug,'post_content'=>$data[1]]);continue;}
  if(($slug==='privacy'&&trim((string)$page->post_content)===trim($old_privacy))||($slug==='terms'&&trim((string)$page->post_content)===trim($old_terms)))wp_update_post(['ID'=>$page->ID,'post_content'=>$data[1]]);
 }
 if(get_option('eicr_core_pages_version')!=='4'){update_option('eicr_core_pages_version','4');flush_rewrite_rules(false);}
}
add_action('init','eicr_ensure_core_pages',40);
